const CH_MAP = {
  TYPE_FACEBOOK: 'Messenger', TYPE_SMS: 'SMS', TYPE_PHONE: 'SMS',
  TYPE_INSTAGRAM: 'Instagram', TYPE_WHATSAPP: 'Messenger',
  TYPE_LIVE_CHAT: 'SMS', TYPE_WEBCHAT: 'SMS', TYPE_VIBER: 'Viber'
};

const raw = $input.all()[0].json;
const convs = raw.conversations || [];

const threads = convs.map(c => {
  const lastMsg = c.lastMessage || c.lastMessageBody || '';
  const unread = c.unreadCount || 0;
  const ts = c.lastMessageDate ? new Date(c.lastMessageDate) : new Date(c.dateAdded || Date.now());
  const nowMs = Date.now();
  const diffMs = nowMs - ts.getTime();
  const diffMin = Math.floor(diffMs / 60000);
  const diffH = Math.floor(diffMs / 3600000);
  const diffD = Math.floor(diffMs / 86400000);
  let when;
  if (diffMin < 60) when = diffMin <= 1 ? 'just now' : `${diffMin}m ago`;
  else if (diffH < 24) when = `${diffH}h ago`;
  else when = `${diffD}d ago`;

  return {
    id: c.id,
    contactId: c.contactId,
    name: c.fullName || c.contactName || 'Client',
    lastMsg: typeof lastMsg === 'string' ? lastMsg.slice(0, 120) : '',
    when,
    unread,
    channel: CH_MAP[c.type] || 'SMS',
    city: c.city || '',
    assignedTo: c.assignedTo || null
  };
});

const totalUnread = threads.reduce((s, t) => s + t.unread, 0);

return [{ json: { threads, totalUnread, total: threads.length, updatedAt: new Date().toISOString() } }];
